package server

import (
	_ "embed"
	"encoding/json"
	"net/http"

	"github.com/ipedrazas/sbx/internal/version"
)

// openapiSpec is the spec generated by the Rust daemon (`dstudiod
// --dump-openapi`); the Go port serves the same API surface.
//
//go:embed openapi.json
var openapiSpec []byte

// OpenAPISpec returns the spec with info.version set to this build's version.
func OpenAPISpec() ([]byte, error) {
	var doc map[string]any
	if err := json.Unmarshal(openapiSpec, &doc); err != nil {
		return nil, err
	}
	if info, ok := doc["info"].(map[string]any); ok {
		info["version"] = version.Version
	}
	return json.MarshalIndent(doc, "", "  ")
}

const swaggerHTML = `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>DStudio Daemon API</title>
  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/swagger-ui-dist@5.17.14/swagger-ui.css">
</head>
<body>
  <div id="swagger-ui"></div>
  <script src="https://cdn.jsdelivr.net/npm/swagger-ui-dist@5.17.14/swagger-ui-bundle.js"></script>
  <script>window.ui = SwaggerUIBundle({ url: "/api-doc/openapi.json", dom_id: "#swagger-ui" });</script>
</body>
</html>`

func registerOpenAPI(mux *http.ServeMux) {
	mux.HandleFunc("GET /api-doc/openapi.json", func(w http.ResponseWriter, _ *http.Request) {
		b, err := OpenAPISpec()
		if err != nil {
			writeError(w, err)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write(b)
	})
	swagger := func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/swagger-ui" {
			http.Redirect(w, r, "/swagger-ui/", http.StatusSeeOther)
			return
		}
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		_, _ = w.Write([]byte(swaggerHTML))
	}
	mux.HandleFunc("GET /swagger-ui", swagger)
	mux.HandleFunc("GET /swagger-ui/", swagger)
}
